---@class OverseaManageSettingCalculationNode
local OverseaManageSettingCalculationNode = Class('OverseaManageSettingCalculationNode')
local UIEventProxy = CS.Engine.UI.UIEventProxy
local EasyTouch =  CS.HedgehogTeam.EasyTouch.EasyTouch
local KTool = CS.Engine.Lib.KTool
local QuickLongTapType = typeof(CS.HedgehogTeam.EasyTouch.QuickLongTap)
local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")

function OverseaManageSettingCalculationNode:__init()
    
end

function OverseaManageSettingCalculationNode:__delete()
    EasyTouch.instance.enableUIMode = false
    EasyTouch.SetUICompatibily( true)
end

function OverseaManageSettingCalculationNode:Awake()
    self:AddUIClick()
end

function OverseaManageSettingCalculationNode:AddUIClick()
    self.longAddTapComp = KTool.GetOrAddComponent(self.BtnAdd.gameObject, QuickLongTapType)
    self.longAddTapComp.onLongTap:AddListener(Bind(self, self.OnBtnAddPointDown))

    self.longReduceTapComp = KTool.GetOrAddComponent(self.BtnReduce.gameObject, QuickLongTapType)
    self.longReduceTapComp.onLongTap:AddListener(Bind(self, self.OnBtnReducePointDown))

    self.InputField.onValueChanged:AddListener(Bind(self, self.InputFieldListener))

    SetButtonAction(self.BtnAdd.gameObject,Bind(self,self.OnAddBtnClick))
    SetButtonAction(self.BtnReduce.gameObject,Bind(self,self.OnDelBtnClick))
end

function OverseaManageSettingCalculationNode:RefreshShowInfo(data, curTabIndex,isAuto)
    self.data = data
    self.curTabIndex = curTabIndex
    self.curSellNum = 1

    self.sellSingle = 0
    self.costSingle = 0
    self.getSingle = 0
    self.maxSellNum = 1
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    self.sellSingle,self.costSingle,self.getSingle,self.maxSellNum = component:CalculationMenuPrice(self.curTabIndex,self.data)
    ---快速添加 直接拉满
    if isAuto then
        self.curSellNum = self.maxSellNum
    end
    self:RefreshShow()
end

function OverseaManageSettingCalculationNode:SetStatus(status)
    KTool.SetActive(self.controller.gameObject,status)
end

function OverseaManageSettingCalculationNode:RefreshShow()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local volume = component:GetIsLockedAndVolume(self.curTabIndex)
    local str = table.concat({self.curSellNum,"/",volume})
    self.InputField.text = str
    self:RefreshTimeShow()
    local goodsId = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(7).num
    CfUtils.FillText(self.TextNumber1,math.floor(checkNumber(self.sellSingle * self.curSellNum)))
    CfUtils.FillText(self.TextNumber2,math.floor(checkNumber(self.costSingle * self.curSellNum)))
    CfUtils.FillText(self.TextNumber3,math.floor(checkNumber(self.getSingle * self.curSellNum)))

    ---@type GoodsVo
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    for i = 1, 3 do
        local icon = self["ImgGoodsIcon"..i]
        if icon and goodsVo then
            CfUtils.FillImage(icon,goodsVo.photoPath)
        end
    end
    CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop.gameObject, goodsId, math.floor(checkNumber(self.costSingle * self.curSellNum)))
end
---这里的时间 可能还要减去buff的时间
function OverseaManageSettingCalculationNode:RefreshTimeShow()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local baseTime = component:GetMenuBaseTime()
    local AllTime = baseTime * self.curSellNum
    CfUtils.FillText(self.SellTime.gameObject,CfUtils.GetTimeHMS(checkNumber(AllTime)))
end

function OverseaManageSettingCalculationNode:Start()

end

function OverseaManageSettingCalculationNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

function OverseaManageSettingCalculationNode:OnBtnAddPointDown()
    self.curSellNum = self.curSellNum + 1
    if self.curSellNum > self.maxSellNum then
        self.curSellNum = self.maxSellNum
    end
    self:RefreshShow()
end

function OverseaManageSettingCalculationNode:InputFieldListener()
    if not isNull(self.curSellNum) then
        if self.curSellNum > self.maxSellNum then
            self.curSellNum = self.maxSellNum
        end
        if self.curSellNum <= 1 then
            self.curSellNum = 1
        end
        self:RefreshShow()
    end
end

function OverseaManageSettingCalculationNode:OnAddBtnClick()
    self.curSellNum = self.curSellNum + 1
    if self.curSellNum > self.maxSellNum then
        GameUtils.Toast(localize("当前套餐可上架份数已达上限"))
        self.curSellNum = self.maxSellNum
        return
    end
    self:RefreshShow()
end

function OverseaManageSettingCalculationNode:OnDelBtnClick()
    self.curSellNum = self.curSellNum - 1
    if self.curSellNum <= 1 then
        self.curSellNum = 1
    end
    self:RefreshShow()
end

function OverseaManageSettingCalculationNode:OnBtnReducePointDown()
    self.curSellNum = self.curSellNum - 1
    if self.curSellNum <= 1 then
        self.curSellNum = 1
    end
    self:RefreshShow()
end

return OverseaManageSettingCalculationNode